// One question from sky.txt: a sky photo, its question and three answers
class SkyQuestion
{
    public string Picture { get; set; }       // the photo's file name
    public string Name { get; set; }          // like Thunderstorm cloud
    public string Question { get; set; }      // the question
    public string[] Answers { get; set; }     // the three answers
    public int Right { get; set; }            // the right answer, 0 to 2
    public string Explanation { get; set; }   // why it is right

    // Makes one SkyQuestion from a line of sky.txt, split at each |
    public SkyQuestion(string[] parts)
    {
        Picture = parts[0];
        Name = parts[1];
        Question = parts[2];
        Answers = new string[] { parts[3], parts[4], parts[5] };
        Right = Convert.ToInt32(parts[6]) - 1;
        Explanation = parts[7];
    }

    // Reads every question in sky.txt into a list
    public static List<SkyQuestion> LoadAll()
    {
        List<SkyQuestion> questions = new List<SkyQuestion>();
        string path = Files.Data("sky.txt");
        if (!File.Exists(path)) return questions; // no file: empty list
        StreamReader reader = new StreamReader(path);
        while (!reader.EndOfStream)
        {
            string line = reader.ReadLine();
            string[] parts = line.Split('|');
            if (parts.Length != 8) continue;    // skip a broken line
            questions.Add(new SkyQuestion(parts));
        }
        reader.Close();
        return questions;
    }
}

// ---------- the game-form methods from chapter 9 ----------

// Keeps the result on the map, even if the window is then closed
private void KeepResult()
{
    Expedition.Finish(gameNumber, result);
    finished = true;
    lblScore.Text = "Points: " + result.Score;
}

// Fills in the Round over panel and brings it to the front
private void ShowRoundOver()
{
    lblRoundScore.Text = "You scored " + result.Score
        + " out of 100 points.";
    lblWellList.Text = ListText(result.WentWell,
        "thing that went well", "things that went well");
    lblWrongList.Text = ListText(result.WentWrong,
        "thing that went wrong", "things that went wrong");
    if (result.Score >= 60) Sound.Play("win.wav");
    else Sound.Play("lose.wav");
    pnlRoundOver.Visible = true;
    pnlRoundOver.BringToFront();
}

// Up to 3 lines from a list, then how many more there are
private string ListText(List<string> lines, string one, string many)
{
    if (lines.Count == 0) return "Nothing this time.";
    string text = "";
    for (int i = 0; i < lines.Count && i < 3; i++)
    {
        text = text + "- " + lines[i] + Environment.NewLine;
    }
    int more = lines.Count - 3;
    if (more == 1) text = text + "And 1 more " + one + ".";
    if (more > 1) text = text + "And " + more + " more " + many + ".";
    return text;
}

// Back to the map: closing the window runs FormClosing
private void btnBack_Click(object sender, EventArgs e)
{
    this.Close();
}

// The Round over panel's Back to the map button
private void btnDone_Click(object sender, EventArgs e)
{
    this.Close();
}

// Runs as the window closes, by Back, by Done or by the X
private void frmSky_FormClosing(object sender,
    FormClosingEventArgs e)
{
    if (finished) return;    // a finished round closes at once
    DialogResult answer = MessageBox.Show("Leave Read the Sky? It "
        + "will score nothing, but you can come back and climb it "
        + "again.", "Summit Ready", MessageBoxButtons.YesNo);
    if (answer == DialogResult.No) e.Cancel = true;   // stay
}

// Shows the speaker picture that matches the sound being on or off
private void ShowSpeaker()
{
    string icon = "icon-speaker-on-64.png";
    if (Sound.Muted) icon = "icon-speaker-muted-64.png";
    picSound.Image = Files.Picture("Icons", icon);
}

// The speaker picture turns the sound off, or back on
private void picSound_Click(object sender, EventArgs e)
{
    Sound.Muted = !Sound.Muted;
    ShowSpeaker();
}

private void frmSky_Load(object sender, EventArgs e)
{
    // Runs once, right before the window first appears
    ShowSpeaker();
    answers = new Button[] { btnAnswer1, btnAnswer2, btnAnswer3 };
    questions = SkyQuestion.LoadAll();
    if (questions.Count < 10)
    {
        lblQuestion.Text = "Read the Sky needs 10 questions in "
            + "Data\\sky.txt, each with 8 parts.";
        return;
    }
    order = Mix.ShuffledNumbers(questions.Count);
    ShowQuestion();
}

// Puts question number on the screen and starts the time bar
private void ShowQuestion()
{
    SkyQuestion q = questions[order[number]];
    lblCount.Text = "Question " + (number + 1) + " of 10";
    lblQuestion.Text = q.Question;
    picSky.Image = Files.Picture("Sky", q.Picture);
    lblExplain.Text = "";
    int[] mixed = Mix.ShuffledNumbers(3);
    for (int i = 0; i < 3; i++)
    {
        answerOf[i] = mixed[i];
        answers[i].Text = q.Answers[mixed[i]];
        answers[i].BackColor = Color.White;
        answers[i].ForeColor = Color.FromArgb(38, 50, 56);
        answers[i].Cursor = Cursors.Hand;
    }
    answered = false;
    btnNext.Visible = false;
    timeLeft = 100;
    prgTime.Value = 100;
    tmrQuestion.Start();
}

// Every 0.1 seconds the time bar goes down by 1
private void tmrQuestion_Tick(object sender, EventArgs e)
{
    timeLeft--;
    prgTime.Value = timeLeft;
    if (timeLeft == 30 || timeLeft == 20 || timeLeft == 10)
    {
        Sound.Play("tick.wav");    // the last 3 seconds
    }
    if (timeLeft == 0) Answer(-1);  // time is up: counts as wrong
}

// One of the three answer buttons was clicked
private void Answer_Click(object sender, EventArgs e)
{
    if (answered) return;          // this question is done already
    for (int i = 0; i < 3; i++)
    {
        if (sender == answers[i]) Answer(i);
    }
}

// Marks the answer on button picked (-1 when the time ran out)
private void Answer(int picked)
{
    tmrQuestion.Stop();
    answered = true;
    SkyQuestion q = questions[order[number]];
    for (int i = 0; i < 3; i++)
    {
        answers[i].Cursor = Cursors.Default;
        if (answerOf[i] == q.Right)
        {
            answers[i].BackColor = Color.FromArgb(62, 142, 65);
            answers[i].ForeColor = Color.White;
        }
        else if (i == picked)
        {
            answers[i].BackColor = Color.FromArgb(178, 58, 46);
            answers[i].ForeColor = Color.White;
        }
    }
    string best = q.Answers[q.Right];
    string name = FirstLower(q.Name);

    if (picked != -1 && answerOf[picked] == q.Right)
    {
        right++;
        lblExplain.Text = "Correct. " + q.Explanation;
        wellLines.Add("You read the " + name + " right.");
        Sound.Play("correct.wav");
    }
    else
    {
        if (picked == -1)
        {
            lblExplain.Text = "Time is up. The best answer is: "
                + best + ". " + q.Explanation;
        }
        else
        {
            lblExplain.Text = "Not quite. The best answer is: "
                + best + ". " + q.Explanation;
        }
        wrongLines.Add("You missed the " + name + " question.");
        Sound.Play("wrong.wav");
    }
    if (number == 9)
    {
        btnNext.Text = "See my score";
        RecordResult();
    }
    btnNext.Visible = true;
}

// The name with a small first letter, so it reads in a sentence
private string FirstLower(string name)
{
    return name.Substring(0, 1).ToLower() + name.Substring(1);
}

// Next question, or See my score after question 10
private void btnNext_Click(object sender, EventArgs e)
{
    if (number == 9)
    {
        ShowRoundOver();
        return;
    }
    number++;
    ShowQuestion();
}

// Works out the score, adds the feedback, then keeps the result
private void RecordResult()
{
    int score = right * 10;
    result = new GameResult("Read the Sky", score);
    result.WentWell.AddRange(wellLines);
    result.WentWrong.AddRange(wrongLines);
    KeepResult();
}
